/// Reorder `arr` (one extension's constants) into the extension's
/// registration order; constants the table doesn't know keep their order
/// after the known ones.
pub fn order_module_constants(ext: &str, arr: &mut crate::array::PhpArray) {
    let Some((_, order)) = EXT_CONSTANT_ORDER
        .iter()
        .find(|(e, _)| e.eq_ignore_ascii_case(ext))
    else {
        return;
    };
    let rank: crate::fxhash::FxHashMap<&[u8], usize> = order
        .iter()
        .enumerate()
        .map(|(i, n)| (n.as_bytes(), i))
        .collect();
    let mut entries: Vec<(usize, crate::array::ArrayKey, crate::value::Value)> = arr
        .iter()
        .enumerate()
        .map(|(i, (k, v))| {
            let r = match k {
                crate::array::ArrayKey::String(s) => rank.get(s.as_bytes()).copied(),
                _ => None,
            };
            (r.unwrap_or(order.len() + i), k.clone(), v.clone())
        })
        .collect();
    entries.sort_by_key(|(r, _, _)| *r);
    let mut out = crate::array::PhpArray::new();
    for (_, k, v) in entries {
        out.set(k, v);
    }
    *arr = out;
}

/// Add to `arr` the engine constants of module `ext` that no extension
/// listed as its own (fallback_constant_module), as get_defined_constants(true)
/// files them.
pub fn add_unlisted_module_constants(
    vm: &crate::vm::Vm,
    ext: &str,
    arr: &mut crate::array::PhpArray,
) {
    for (name, val) in vm.constants.consts() {
        if vm.constant_files.contains_key(name)
            || vm.module_constants.iter().any(|(_, n)| n.contains(name))
            || !fallback_constant_module(name).eq_ignore_ascii_case(ext)
        {
            continue;
        }
        let key = crate::array::ArrayKey::String(crate::string::PhpString::from_vec(name.clone()));
        if arr.get(&key).is_none() {
            arr.set(key, val.clone());
        }
    }
}

/// The module of an engine constant no extension listed as its own (see
/// Vm::module_constants): its stub's, or the one its prefix tells.
pub fn fallback_constant_module(name: &[u8]) -> &'static str {
    let stub_ext = crate::stub_sigs::CONSTANTS
        .binary_search_by(|c| c.name.as_bytes().cmp(name))
        .ok()
        .map(|i| crate::stub_sigs::CONSTANTS[i].ext);
    if name.starts_with(b"LIBXML_") {
        "libxml"
    } else if name.starts_with(b"MYSQLI_") {
        "mysqli"
    } else if let Some(e) = stub_ext {
        e
    } else if name.starts_with(b"STREAM_")
        || name.starts_with(b"IMAGETYPE_")
        || name == b"YESEXPR"
        || name == b"YESSTR"
    {
        "standard"
    } else if name.starts_with(b"ZLIB_") {
        "zlib"
    } else if name.starts_with(b"Dom\\") || name.starts_with(b"dom\\") {
        "dom"
    } else if name.starts_with(b"MHASH_") {
        "hash"
    } else if name.starts_with(b"MB_") {
        "mbstring"
    } else {
        "Core"
    }
}
